"""Normalize a value name to a valid Python (PEP8 compliant) identifier.

    Args:
        name: The name of a value returned by MPD.

    Returns:
        The normalized name, in all lowercase with - replaced by _.
    """
def normalize(name: str) -> str {
    return name.lower().replace('-', '_');
}

"""
  Suma los digitos de un numero de 2 cifras
  """
def sum_digits(num: int) -> object {
    ult_dig = num % 10;
    pri_dig = num // 10;
    return (pri_dig + ult_dig);
}

""" Resolve a string which represents a boolean value

    Args:
        val: The value
    Returns:
         True, False or None
    """
def resolve_boolean_value(val: str) -> object {
    val = val.upper();
    if (val == "TRUE") {
        return True;
    } elif (val == "FALSE") {
        return False;
    } else {
        return None;
    }
}

"""
    Gets the polymer template sequence from the first
    line of `text`.
    """
def get_polymer_template(text: str) -> str {
    return text.strip().splitlines()[0];
}

"""
    Create a list of dictionaries from a whitespace and newline delimited text.

    For example, this:
    cpu 1100
    ram 640

    cpu 2200
    ram 1024

    becomes:
    [{'cpu': '1100', 'ram': '640'}, {'cpu': '2200', 'ram': '1024'}]
    """
def str2dicts(data: Any) -> object {
    list_data = [];
    list_data.append({});
    d = list_data[-1];
    lines = data.split('\n');
    for line in lines {
        line = line.strip();
        if not line {
            d = {};
            list_data.append(d);
            d = list_data[-1];
            continue;
        }
        whitespace = line.find(' ');
        if not whitespace {
            continue;
        }
        key = line[0:whitespace];
        value = line[(whitespace + 1):];
        d.update({key: value});
    }
    list_data = [
        val
        for val in list_data
        if (val != {})
    ];
    return list_data;
}

"""
    Shuffles the character of a string by placing each of them
    in a grid (the height is dependent on the key) in a zigzag
    formation and reading it left to right.

    >>> encrypt("Hello World", 4)
    'HWe olordll'

    >>> encrypt("This is a message", 0)
    Traceback (most recent call last):
        ...
    ValueError: Height of grid can't be 0 or negative

    >>> encrypt(b"This is a byte string", 5)
    Traceback (most recent call last):
        ...
    TypeError: sequence item 0: expected str instance, int found
    """
def encrypt(input_string: str, key: int) -> str {
    grid = [[] for _ in range(key)];
    lowest = key - 1;
    if (key <= 0) {
        raise ValueError("Height of grid can't be 0 or negative");
    }
    if ((key == 1) or (len(input_string) <= key)) {
        return input_string;
    }
    for (position, character) in enumerate(input_string) {
        num = position % (lowest * 2);
        num = min(num, ((lowest * 2) - num));
        grid[num].append(character);
    }
    grid = ["".join(row) for row in grid];
    output_string = "".join(grid);
    return output_string;
}

"""
    Getting folder name from the splitted file_name
    If the file_name is data_FXVOL_20130612.xml, then the folder name returned will be 'FXVOL'
    """
def scrap_middle_name(file: Any) -> object {
    if (
        file.startswith('data_') and file.endswith('.xml') and (file.count('_') == 2)
    ) {
        split_name = file.split('_');
        return split_name[1];
    }
}

"""Convert a null-terminated C-string bytes to a Python string"""
def cstr2str(cs: Any, encoding: Any = 'utf8') -> object {
    return cs.split(b'\x00', 1)[0].decode(encoding);
}

